; vertical.asm -- chapter 29: a line a frame upwards
; generated by gen29.py
        INCLUDE "msx.inc"
        OUTPUT "vertical.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
count   EQU VARS                ; the frames left
at      EQU VARS + 1            ; the window's column, or the pixels gone by
table   EQU VARS + 3            ; the name table not shown: $18 or $1C, the high byte
ROWS    EQU 21
WIDTH   EQU 64
; Chapter 24's two screens one above the other, a line a frame upwards: the
; 22 pairs of tiles one above the other, shapes and colours, rewritten every
; frame from eight copies in the cartridge; the names every eighth frame.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800, and $1C00 with R#2 = 7
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $0780        ; the status line's letters
        ld hl, glyphs
        ld c, VDP_DATA
        ld b, 80
        otir
        VRAM_WRITE $2780        ; white on black
        ld b, 80
.tc:    ld a, $F1
        out (VDP_DATA), a
        djnz .tc
        VRAM_WRITE $1AA0        ; the status line, in both tables
        ld hl, status
        ld b, 96
        otir
        VRAM_WRITE $1EA0
        ld hl, status
        ld b, 96
        otir
        VRAM_WRITE $0000        ; the pairs at line 0
        ld hl, vshapes
        ld b, 176
        otir
        VRAM_WRITE $2000
        ld hl, vcols
        ld b, 176
        otir
        ld a, $18
        ld (table), a
        xor a
        call window             ; window 0 in the table at $1800
        ld a, $1C
        ld (table), a
        ld a, 1
        call window             ; window 1 in the table at $1C00, not shown
        ld a, 1
        ld (at), a
        VDP_REG 1, $C0          ; the display on
        in a, (VDP_CTRL)        ; F cleared: the first wait ends with a paper
        ld a, 64
        ld (count), a
loop:   call frame              ; the end of the paper
m0:     call show               ; what must change after the paper
m1:     call step               ; the next frame's work, while the paper is drawn
s1:     ld hl, count
        dec (hl)
        jr nz, loop
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret

; show: the pairs' shapes and colours at the new line, 176 bytes of each with
; OTIR, after the paper; at line 0, the table with the next window shown
show:   ld a, (at)
        and 7
        ld l, a
        ld h, 0
        ld de, 176
        call mul                ; HL: the line x 176
        push hl
        VRAM_WRITE $0000
        ld de, vshapes
        add hl, de
        ld c, VDP_DATA
        ld b, 176
        otir                    ; the shapes
        VRAM_WRITE $2000
        pop hl
        ld de, vcols
        add hl, de
        ld b, 176
        otir                    ; and the colours, which move with them
        ld a, (at)
        and 7
        ret nz                  ; seven frames in eight, no more
        ld a, (table)
        cp $18
        ld a, 6
        jr z, .r2
        inc a
.r2:    out (VDP_CTRL), a
        ld a, $80 | 2
        out (VDP_CTRL), a
        ld a, (table)
        xor $18 ^ $1C
        ld (table), a
        ret

; step: after a new table is shown, the next window's pairs written into the
; other one; then a line on
step:   ld a, (at)
        and 7
        jr nz, .on
        ld a, (at)
        rrca
        rrca
        rrca
        and 31
        inc a                   ; the next window's first row
        call window
.on:    ld hl, at
        inc (hl)
        ret

; window: the pairs of the window from row A, 21 rows of 32, into the table
; not shown, at 46 T-states a name
window: ld l, a
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; 32 x the row
        ld de, vpmap
        add hl, de
        xor a
        out (VDP_CTRL), a
        ld a, (table)
        or $40
        out (VDP_CTRL), a
        ld e, ROWS
.row:   ld b, 32
.name:  ld a, (hl)              ;  8
        out (VDP_DATA), a       ; 12
        inc hl                  ;  7
        nop                     ;  5
        djnz .name              ; 14: 46 T-states a name
        dec e
        jr nz, .row
        ret

; mul: HL = HL x DE, HL below 8
